Article "*" -- "1" Category : belongs to
Article "*" -- "1" DistributionCenter : inspected at
Article "*" -- "1" Client : delivered to

DistributionCenter "1" -- "*" H2SEmployee : employs
DistributionCenter "1" -- "*" Article : processes

PickupService "*" -- "1" Resident : scheduled by
DeliveryService "*" -- "1" H2SEmployee : arranged by

@enduml

